local function hsvRainbow(t)
    return Color3.fromHSV((t % 5) / 5, 1, 1)
end

while task.wait() do
    game:GetService("ReplicatedStorage").Configuration["Core Systems"].LockerSystem.EquipLockerItem:FireServer{ SkinColor = hsvRainbow(tick()) }
end
